codeExamples.code:
const int LED = 13;
unsigned long prevMs = 0;
const unsigned long INTERVAL = 500;
bool ledOn = false;
void setup() { pinMode(LED, OUTPUT); }
void loop() {
  unsigned long now = millis();
  if (now - prevMs >= INTERVAL) {
    prevMs = now;
    ledOn = !ledOn;
    digitalWrite(LED, ledOn ? HIGH : LOW);
  }
}

