int readCleanPercent(int pin) {
  long sum = 0;
  for (int i = 0; i < 8; i++) sum += analogRead(pin);
  int avg = sum / 8;
  return constrain(map(avg, 0, 1023, 0, 100), 0, 100);
}
void setup() { Serial.begin(9600); }
void loop() { Serial.println(readCleanPercent(A0)); delay(250); }

